Method.Implementation:
New $namespace
Set $namespace = "%SYS"
if path = "" {
  Return 0
}
Return $GET($$$PythonVenvTag(path),0)

New $namespace
Set $namespace = "%SYS", defaultVenvLocked = 0, argVenvLocked = 0, sc = $$$OK
Try {
  Lock +$$$PythonVenvDefault:30
  If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedX, $name($$$PythonVenvDefault))) }
  Set defaultVenvLocked = 1
  If $D(path) {
    // No-op if empty string
    If (path = "") {
      Lock:defaultVenvLocked -$$$PythonVenvDefault:30
      Return $$$OK
    }
    Lock +$$$PythonVenvTag(path):30
    If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedX, $name($$$PythonVenvTag(path)))) }
    Set argVenvLocked = 1
    // Error if trying to delete default venv to maintain coherence with CPF
    If $D($$$PythonVenvDefault) && (path = $$$PythonVenvDefault) {
      $$$ThrowStatus($$$ERROR($$$VenvError, "Can't delete default venv if still used in CPF settings"))
    }
    If $D($$$PythonVenvTag(path)) {
      Set tag = $$$PythonVenvTag(path)
      Kill $$$PythonVenvPath(tag)
      Kill $$$PythonVenvLib(tag)
      Kill $$$PythonVenvSyspath(tag)
      Kill $$$PythonVenvTag(path)
    }
    Else {
      $$$ThrowStatus($$$ERROR($$$VenvError, path _ " is not a registered venv"))
    }
  }
  // If no argument but default venv is defined, delete everything but the default venv
  Elseif $D($$$PythonVenvDefault) && ($$$PythonVenvDefault '= "") {
    // Save the default venv info
    Set defaultVenv = $$$PythonVenvDefault
    Set defaultTag = $$$PythonVenvTag(defaultVenv)
    Set defaultPath = $$$PythonVenvPath(defaultTag)
    Set defaultLib = $$$PythonVenvLib(defaultTag)
    Set defaultSyspath = $$$PythonVenvSyspath(defaultTag)
    Set venvCount = $$$PythonVenvCount
    // Delete all the venvs definitions
    Lock +$$$PythonVenv:30
    If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedX, $name($$$PythonVenv))) }
    Kill $$$PythonVenv
    Lock -$$$PythonVenv:30, +$$$PythonVenvTag(defaultVenv):30
    If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedX, $name($$$PythonVenvTag(defaultVenv)))) }
    // Restore the default venv info
    Set $$$PythonVenvDefault = defaultVenv
    Set $$$PythonVenvTag(defaultVenv) = defaultTag
    Set $$$PythonVenvPath(defaultTag) = defaultPath
    Set $$$PythonVenvLib(defaultTag) = defaultLib
    Set $$$PythonVenvSyspath(defaultTag) = defaultSyspath
    Set $$$PythonVenvCount = venvCount
    Lock -$$$PythonVenvTag(defaultVenv):30
  }
  // If no default venv and no argument, then wipe everything
  Else {
    Lock +$$$PythonVenv:30
    If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedX, $name($$$PythonVenv))) }
    Kill $$$PythonVenv
    Lock -$$$PythonVenv:30
  }
} Catch ex {
  set sc = ex.AsStatus()
}
Lock:argVenvLocked -$$$PythonVenvTag(path):30
Lock:defaultVenvLocked -$$$PythonVenvDefault:30
If $$$ISERR(sc) { $$$ThrowStatus(sc) }
Return sc

New $namespace
if x = 2 {
 w "hello"
}
 Set $namespace = "%SYS", argVenvLocked = 0, sc = $$$OK, loadedVenvTag = 0, loadedVenvName = ""
 Try {
   If absolutepath = "" {
     Return $$$OK
   }
   Set loadedTagName = $$$GetPythonVenvTagName
   Set loadedVenvTag = $P(loadedTagName,",",1)
   Set loadedVenvName = $P(loadedTagName,",",2)
   print
   zprint
   if ($System.Process.JobType($j)=$$$CSPSRV) {
    If 'overridesafe { $$$ThrowStatus($$$ERROR($$$VenvError, "Cannot activate a venv manually in a CSP job, define a venv for the web application instead.")) }
   }
   Set normalizedPath = ##class(%File).NormalizeFilename(absolutepath)
   Lock +$$$PythonVenvTag(normalizedPath)#"S":30
   If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedS, $name($$$PythonVenvTag(normalizedPath)))) }
   Set argVenvLocked = 1
   Set venvtag = $GET($$$PythonVenvTag(normalizedPath))
   If venvtag = "" {
    Lock -$$$PythonVenvTag(normalizedPath)#"S":30
    Set argVenvLocked = 0
    Do ..RegisterVenv(normalizedPath)
    Lock +$$$PythonVenvTag(normalizedPath)#"S":30
    If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedS, $name($$$PythonVenvTag(normalizedPath)))) }
    Set argVenvLocked = 1
    Set venvtag = $GET($$$PythonVenvTag(normalizedPath))
    If 'venvtag { $$$ThrowStatus($$$ERROR($$$VenvError,"venvtag is expected to be set but it is not set.")) }
   } Else {
      Set sc = ..ValidateVenv(normalizedPath)
      If $$$ISERR(sc) { $$$ThrowStatus(sc) }
   }
   Set venvname = ##class(%File).GetDirectoryPiece(normalizedPath, -1)
   // If trying to activate currently activated venv, exit cleanly
   If (venvtag = loadedVenvTag) && (venvname = loadedVenvName) {
     Lock:argVenvLocked -$$$PythonVenvTag(normalizedPath)#"S":30
     Return sc
   }
   Set venvdef = $GET($$$PythonVenvSyspath(venvtag))
   Do $$$SetPythonVenvTagName(venvtag,venvname)
   Do ..ActivateVenvDetail(venvdef)
 } catch ex {
   // Reset venvtag and venvname to original ones
   If (loadedVenvName '= "") {
     Do $$$SetPythonVenvTagName(loadedVenvTag, loadedVenvName)
   } Else {
     Do $$$SetPythonVenvTag(loadedVenvTag)
   }
   Set sc = ex.AsStatus()
 }
 Lock:argVenvLocked -$$$PythonVenvTag(normalizedPath)#"S":30
 If $$$ISERR(sc) {
   If ($$$ERRORISTYPE(sc, $$$DirectoryNotExist)) && (venvtag '= "") {
     Do ..PurgeVenvs(normalizedPath)
   }
   $$$ThrowStatus(sc)
 }
 Set existingPrompt= ##class(%SYSTEM.Process).TerminalPrompt()
 // Don't change the prompt if venv (corresponds to 9) is already in it
 If existingPrompt '[ "9" {
   // Can't add venv to the prompt if the prompt is full
   If $LL($LFS(existingPrompt)) '= 9 {
     Set cmdNewPrompt="do $SYSTEM.Process.TerminalPrompt(9,"
     For i=1:1 {
       Set Val=$p(existingPrompt,",",i)
       Quit:Val=""
       Set cmdNewPrompt=cmdNewPrompt_Val_","
     }
     Set cmdNewPrompt=$e(cmdNewPrompt,1,*-1)_")"
     // Error checking?
     Xecute cmdNewPrompt
   }
 }
 Return sc

New $namespace
Set $namespace = "%SYS"
// Get the rootDir directory (OS independent but a bit hacky)
Set rootDir = ""
Do {
  Set prev = rootDir
  Set rootDir = ##class(%File).ParentDirectoryName(rootDir)
} While prev '= rootDir
// Check that argument is provided
If (venvpath = "") || (venvpath = rootDir) {
  Return $$$ERROR($$$InvalidArgument)
}
// Check that argument is an absolute path
If ($EXTRACT(venvpath, 1, $LENGTH(rootDir)) '= rootDir) {
  Return $$$ERROR($$$RelativeVenvPathsNotSupported)
}
// Normalize argument for more robust comparison
Set normalizedVenvPath = ##class(%File).NormalizeFilename(venvpath)
// Construct the path to the activate script of the venv
Do ##class(%File).Deconstruct(normalizedVenvPath, .venvpathdirs)
Set accessDeniedError = 0, directoryNotFoundError = 0, directoryExpectedError = 0
if $$$isUNIX {
  Set venvpathdirs($INCREMENT(venvpathdirs)) = "bin"
  Set venvpathdirs($INCREMENT(venvpathdirs)) = "activate"
  Set accessDeniedError = -13, directoryNotFoundError = -2, directoryExpectedError = -20
}
else {
  Set venvpathdirs($INCREMENT(venvpathdirs)) = "Scripts"
  Set venvpathdirs($INCREMENT(venvpathdirs)) = "Activate.ps1"
  Set accessDeniedError = -5, directoryNotFoundError = -2
}
Set activatePath = ##class(%File).Construct(venvpathdirs...)
// Check that directory exists and can be accessed
If '##class(%File).Exists(activatePath, .err) {
  Set parent = activatePath
  While parent '= rootDir {
    Set prevErr = err
    Set child = parent
    Set parent = ##class(%File).ParentDirectoryName(parent)
    If ##class(%File).Exists(parent, .err) {
      // Error is because of access denied
      If prevErr = accessDeniedError {
        Return $$$ERROR($$$DirectoryPermission,parent)
      }
      Elseif prevErr = directoryNotFoundError {
        // Error is because provided directory is not a venv
        If parent [ normalizedVenvPath {
          Return $$$ERROR($$$NoActivateVenvScript,parent)
        }
        // Error is because provided directory doesn't exist
        Else {
          Return $$$ERROR($$$DirectoryNotExist,child)
        }
      }
      Elseif ($$$isUNIX) && (prevErr = directoryExpectedError) {
          // Error because expected directory name but found file name instead
          Return $$$ERROR($$$DirectoryNotExist,child)
      }
      // Other cases possible? General error for these?
      Else {
        Return $$$ERROR($$$VenvError,"Error (code "_prevErr_") with "_parent)
      }
    }
  }
} Else {
  // Add permission check on the activate script?
  Return $$$OK
}

 New $namespace
 Set $namespace = "%SYS"
 If absolutepath = "" {
   Return $$$OK
 }
 // Check that absolutepath is a usable venv
 Set normalizedPath = ##class(%File).NormalizeFilename(absolutepath)
 Set sc = ..ValidateVenv(normalizedPath)
 If $$$ISERR(sc) {
   $$$ThrowStatus(sc)
 }
 Lock +$$$PythonVenvTag(normalizedPath):30
 If '$TEST { $$$ThrowStatus($$$ERROR($$$LockFailedX, $name($$$PythonVenvTag(normalizedPath)))) }
 Set venvdef = $GET($$$PythonVenvTag(normalizedPath))
 If venvdef '= "" {
  Lock -$$$PythonVenvTag(normalizedPath):30
  //TODO perhaps some processing, right now this is just the pythonpath
  // Already registered, exit (or maybe we should redo it?)
  Quit $$$OK
 }
 Set flag = $SYSTEM.Process.SetZEOF(1) // No throwing on eof
 Kill syspath //Kill pythonlib
 Set syspath = "" //Set pythonlib = ""
 Try {
   Kill dirs
   Set dirs($i(dirs))=$system.Util.LibPythonDirectory()
   Set dirs($i(dirs))="getVenvDetail"
   Set getVenvDetailScript = ##class(%File).Construct(dirs...)
   Kill dirs
   Set dirs($i(dirs))=$system.Util.LibPythonDirectory()
   Set dirs($i(dirs))="python_utils"
   Set dirs($i(dirs))="venvdetail.py"
   Set printSyspathScript = ##class(%File).Construct(dirs...)
   Set command = ""
   Set fileExtension = ""
   Set args = ""
   If ($SYSTEM.Version.GetOS() = "Windows") {
     Set command = "powershell.exe"
     Set fileExtension = ".ps1"
     Set args($increment(args)) = "-ExecutionPolicy"
     Set args($increment(args)) = "RemoteSigned"
     Set args($increment(args)) = "-File"
   } Elseif ($SYSTEM.Version.GetOS() = "UNIX") {
     Set command = "sh"
     Set fileExtension = ".sh"
   }
   Set args($increment(args)) = getVenvDetailScript_fileExtension
   Set args($increment(args)) = normalizedPath
   Set args($increment(args)) = printSyspathScript
   Open "|CPIPE|":(/COMMAND=command:/ARGS=args...:"R":/TRANSLATE=0:/IOTABLE="UTF8"):10
   If '$TEST { $$$ThrowStatus($$$ERROR($$$GeneralError, "Open timeout")) }
   Use "|CPIPE|"
   Set syspath = ""
   Set numpaths = 0
   Read line:10
   set maybeErr = line
   If '$TEST { $$$ThrowStatus($$$ERROR($$$GeneralError, "Read timeout")) }
   Set start = 0
   While (line'="") {
		 Do ##Class(%SYS.System).WriteToConsoleLog("iterated"_line, 0, 2)
     // This validates that each line is feasibly a path, otherwise, something has likely gone wrong.
     If $MATCH(line,".*[\\\/].*")=0{
      $$$ThrowStatus($$$ERROR($$$VenvError,line))
     }
     Set syspath = syspath_$C(0)_line
     Set numpaths = numpaths + 1
     Read line:10
     If '$TEST { $$$ThrowStatus($$$ERROR($$$GeneralError, "Read timeout")) }
   }
   if numpaths < 2 {
      $$$ThrowStatus($$$ERROR($$$VenvError,maybeErr))
   }
 } Catch ex {
   Close "|CPIPE|"
   Lock -$$$PythonVenvTag(normalizedPath):30
   Set sc = ex.AsStatus()
   $$$ThrowStatus(sc)
 }
 // restore process state
 Do $SYSTEM.Process.SetZEOF(flag)
 If ($IO = "|CPIPE|") {
   Close "|CPIPE|"
 }

  Set venvtag = $INCREMENT($$$PythonVenvCount)
  Set $$$PythonVenvTag(normalizedPath) = venvtag
  Set $$$PythonVenvPath(venvtag) = normalizedPath
  Set $$$PythonVenvLib(venvtag) = "" //pythonlib
  Set $$$PythonVenvSyspath(venvtag) = syspath
  Lock -$$$PythonVenvTag(normalizedPath):30
  Return sc

if "" = ..GetRunningLibrary() {q "Not Loaded"}
else {
	set sys=##class(%SYS.Python).Import("sys")
	s version = sys.version
	s version = $TR(version,$C(10),"")
	q version
}

#dim status As %Status = $$$OK
#dim signalstate As %Integer = ""
#dim stdiomode As %Integer = ""
#dim locals As %Integer = ""
Try {
	// Must have %Developer:USE to use Shell()
	If '$system.Security.Check($$$DevelopmentResourceName,$$$PermUseName) {
		Set status = $$$ERROR($$$OperationRequires,$$$DevelopmentResourceName_":"_$$$PermUseName)
		Quit
	}

	// Set command line recall context for Python.  Note when in PY mode, the command line
	// recall will treat Ctrl-D on an empty line as a termination character (it will not if
	// there are characters in the line).
	Do $system.Process.NewLineRecallContext("PY")

	// Enable signal/stdio processing
	Set signalstate = ..ChangeSignalState(0)
	Set stdiomode   = ..SetStdIOMode(3)

	Set sys      = ..Import("sys")
	Set code     = ..Import("code")
	Set builtins = ..Import("builtins")
	Set locals   = ..Builtins().dict()


	// Copy top level locals objects into the python space
	If vars {
		Set locals = ..Builtins().dict()
	    Set var=""
		For {
			Set var = $ORDER(@var)
			Quit:var=""

			If $Data(@var)#2,$IsObject(@var) {
				Do locals."__setitem__"(var,@var)
			}
		}
	}

	Write !,"Python ",$REPLACE(sys.version,$C(10),$C(13,10))," on ",sys.platform,!
	Write "Type quit() or Ctrl-D to exit this shell.",!

	Set interpreter = code.InteractiveInterpreter(locals)
	Do interpreter.runsource("import iris")
	Set more = 0
	Set buffer = ""
	For {
		Write $S(more:"...",1:">>>")," "
		Read ln,!

		// Exit on Ctrl-D on an empty line
		Quit:$ZB=$C(4)

		Set buffer = buffer _ $LB(ln)
		Set src = $LTS(buffer,$C(10))
		#; Use $xecute so global write requests will not be seen as
		#; coming from a %SYS routine. If this is moved to a non-%
		#; routine, it can be restored to the original:
		#; Set more = interpreter.runsource(src)
		Set more = $xecute("(int,src) quit int.runsource(src)",interpreter,src)
		If 'more {
			// Reset the buffer when done with multi-line statements
			Set buffer = ""
		}
	}

} Catch ex {
	// The shell might throw a SystemExit if the user calls quit(), so we ignore it
	If ex.Data'["'SystemExit'" {
		Set status = ex.AsStatus()
	}
}

If locals'="" {
    do locals.clear()
}

// Restore previous signal state and stdio mode
Do:signalstate'="" ..ChangeSignalState(signalstate)
Do:stdiomode'="" ..SetStdIOMode(stdiomode)

// Report any errors we encountered (this is an interactive shell after all)
If $$$ISERR(status) {
    Do $system.OBJ.DisplayError()
	Write !
}

Quit status
